INSERT INTO lessons (slug, title, content) VALUES ('k8s-troubleshooting', 'Debugging Pods, Kubelet, & Control Plane', '## Debugging Pods, Kubelet, & Control Plane\n\n### Debugging Pods\n- Use `kubectl describe pod <pod-name>` to get detailed information about a pod including its status, events, and other metadata.\n- Employ `kubectl logs <pod-name>` to retrieve the logs from a container within a pod. This is useful for diagnosing issues related to the application running inside the container.\n- Use `kubectl exec <pod-name> -- <command>` to run commands inside the pod to inspect its state or execute scripts for troubleshooting.\n\n### Debugging Kubelet\n- Kubelet is the primary "node agent" that runs on each node. It is responsible for making sure that containers are running in a pod.\n- Kubelet can be debugged by checking its logs with `journalctl -u kubelet` on a Linux system. This can help identify issues related to configuration or resource management.\n- Use `kubectl get nodes` and `kubectl describe node <node-name>` to check the health and status of nodes where kubelet is running.\n\n### Debugging Control Plane\n- The control plane is responsible for maintaining the desired state of the cluster. It includes components like the API server, scheduler, and controller manager.\n- Use `kubectl get cs` to check the status of the control plane components.\n- For more detailed information, you can check the logs of the control plane components, often found in `/var/log` on the control plane nodes.\n') ON CONFLICT (slug) DO NOTHING;
INSERT INTO quizzes (lesson_id, question, options, correct_index, explanation) VALUES 
  ((SELECT id FROM lessons WHERE slug='k8s-troubleshooting'), 'Which command is used to check the status of the control plane components?', '["kubectl get cs", "kubectl describe pod", "kubectl exec", "kubectl logs"]'::jsonb, 0, 'The `kubectl get cs` command is used to check the status of the control plane components in a Kubernetes cluster.'),
  ((SELECT id FROM lessons WHERE slug='k8s-troubleshooting'), 'What is the primary purpose of using `kubectl describe pod <pod-name>`?', '["To execute commands inside a pod.", "To retrieve the logs from a pod.", "To get detailed information about a pod, including its status, events, and other metadata.", "To check the health of nodes where kubelet is running."] '::jsonb, 2, 'Using `kubectl describe pod <pod-name>` provides detailed information about a pod, including its status, events, and other metadata, which is useful for troubleshooting issues with pods.');